    /** @return array<string, RouteSpec> every route by operationId, in contract order */
    public static function all(): array
    {
        $out = [];
        foreach (self::OPERATIONS as $operationId) {
            $out[$operationId] = self::get($operationId);
        }

        return $out;
    }
